/* QA PDF hotfix V33.1.1 (2026-09-24): iframe-safe PDF options. */
const COMPANY_LOGO_BASE64 = '';
function buildJobPdfHtml_(job, documentType, isFinal) {

  const logs =
    job.correctiveLogs || [];

  const logoData =
    'data:image/png;base64,' +
    COMPANY_LOGO_BASE64;

  const parts = [];

  parts.push(
    '<!doctype html>',
    '<html>',
    '<head>',
    '<meta charset="UTF-8">',
    '<style>',
    pdfCss_(),
    '</style>',
    '</head>',
    '<body>',

    '<table class="header">',
      '<tr>',
        '<td class="logo-col">',
          '<img class="company-logo" src="',
            logoData,
          '">',
        '</td>',
        '<td class="title-col">',
          '<div class="main-title">INTER-DEPARTMENT PROBLEM NOTICE</div>',
          '<div class="thai-title">ใบแจ้งปัญหาระหว่างแผนก</div>',
        '</td>',
      '</tr>',
    '</table>',

    '<div class="top-rule"></div>',

    '<div class="doc-status">',
      pdfEscapeHtml_(documentType),
      ' &nbsp; | &nbsp; ',
      pdfEscapeHtml_(job.jobId),
    '</div>'
  );

  if (!isFinal) {
    parts.push(
      '<div class="draft-note">',
        'DRAFT - งานยังไม่ปิดโดย QA',
      '</div>'
    );
  }

  // 1. GENERAL INFORMATION
  parts.push(
    pdfSectionTableHtml_(
      '1. ข้อมูลการแจ้งเรื่อง (GENERAL INFORMATION)',
      [
        {
          type: 'four',
          values: [
            'เลขที่เอกสาร (Doc No.)',
            job.jobId,
            'วันที่แจ้ง (Date)',
            job.createdDateTime
          ]
        },
        {
          type: 'four',
          values: [
            'ผู้แจ้งเรื่อง (Issuer)',
            job.issuerName,
            'สถานะงาน (Status)',
            job.status
          ]
        },
        {
          type: 'four',
          values: [
            'แผนกที่แจ้ง (From)',
            job.fromDepartment,
            'แผนกที่รับแจ้ง (To)',
            job.toDepartment
          ]
        }
      ]
    )
  );

  // 2. PROBLEM DETAILS
  parts.push(
    pdfSectionTableHtml_(
      '2. รายละเอียดปัญหาที่พบ (PROBLEM DETAILS)',
      [
        {
          type: 'four',
          values: [
            'ประเภทปัญหา (Category)',
            job.category,
            'สถานที่/ไลน์ (Location)',
            job.location
          ]
        },
        {
          type: 'four',
          values: [
            'ผลกระทบ (Impact)',
            job.impact,
            'เวลาที่เสียไป (Downtime)',
            job.downtimeMin !== null && job.downtimeMin !== ''
              ? String(job.downtimeMin) + ' นาที'
              : '-'
          ]
        },
        {
          type: 'four',
          values: [
            'Priority',
            job.priority,
            'Serial No.',
            job.serialNo
          ]
        },
        {
          type: 'two',
          values: [
            'รายละเอียดปัญหา',
            job.problemDetail
          ]
        }
      ]
    )
  );

  // BEFORE
  parts.push(
    pdfImageSectionHtml_(
      'ภาพประกอบปัญหา (BEFORE)',
      job.beforeImages || []
    )
  );

  // CORRECTIVE / REWORK
  if (logs.length === 0) {

    parts.push(
      pdfSectionTableHtml_(
        '3. การแก้ไขและแนวทางป้องกัน (CORRECTIVE & PREVENTIVE ACTION)',
        [
          {
            type: 'two',
            values: [
              'สถานะ',
              'ยังไม่มีการส่งผลการแก้ไขให้ QA ตรวจ'
            ]
          }
        ]
      )
    );

  } else {

    logs.forEach(function(log) {

      const sectionNo =
        2 + Number(log.roundNo || 0);

      const title =
        Number(log.roundNo) === 1
          ? sectionNo +
            '. การแก้ไขและแนวทางป้องกัน (CORRECTIVE & PREVENTIVE ACTION)'
          : sectionNo +
            '. การแก้ไขเพิ่มเติม (REWORK ACTION) - รอบที่ ' +
            log.roundNo;

      parts.push(
        pdfSectionTableHtml_(
          title,
          [
            {
              type: 'two',
              values: [
                Number(log.roundNo) === 1
                  ? 'การแก้ไขเบื้องต้น'
                  : 'การแก้ไขเพิ่มเติม',
                log.correctiveAction
              ]
            },
            {
              type: 'two',
              values: [
                'แนวทางป้องกันซ้ำ',
                log.preventiveAction
              ]
            },
            {
              type: 'four',
              values: [
                'ผู้รับผิดชอบ (Assignee)',
                log.assigneeName,
                'วันที่ส่ง QA',
                log.dateTime
              ]
            }
          ]
        )
      );

      parts.push(
        pdfImageSectionHtml_(
          'ภาพหลังการแก้ไข (AFTER ' +
            log.roundNo +
            ')',
          log.afterImages || []
        )
      );

      let qaResult =
        'รอ QA ตรวจ';

      if (
        String(log.result || '').toUpperCase() ===
        'PASS'
      ) {
        qaResult =
          'PASS / ผ่าน';
      }

      if (
        String(log.result || '').toUpperCase() ===
        'REJECT'
      ) {
        qaResult =
          'REJECT / ไม่ผ่าน';
      }

      parts.push(
        pdfSectionTableHtml_(
          'ผลตรวจ QA รอบที่ ' +
            log.roundNo,
          [
            {
              type: 'four',
              values: [
                'ผลตรวจ QA',
                qaResult,
                'ผู้ตรวจ QA',
                log.qaInspector || '-'
              ]
            },
            {
              type: 'two',
              values: [
                'ข้อเสนอแนะ / ความเห็น QA',
                log.qaComment
              ]
            }
          ]
        )
      );

    });

  }

  // SIGN-OFF
  const signoffNo =
    logs.length
      ? 3 + logs.length
      : 4;

  const issuerStatus =
    String(job.status || '').toUpperCase() ===
    'OPEN'
      ? 'OPEN'
      : 'ISSUED';

  const assigneeStatus =
    [
      'IN_PROGRESS',
      'WAITING_QA',
      'REWORK',
      'CLOSED'
    ].indexOf(
      String(job.status || '').toUpperCase()
    ) >= 0
      ? job.status
      : '-';

  parts.push(
    pdfSignoffHtml_(
      signoffNo +
        '. การลงนามและสถานะงาน (SIGN-OFF & STATUS)',
      [
        [
          'ผู้แจ้งเรื่อง (Issuer)',
          job.issuerName,
          job.createdDateTime,
          issuerStatus
        ],
        [
          'ผู้รับแจ้ง (Assignee)',
          job.assigneeName || '-',
          job.correctiveDateTime || '-',
          assigneeStatus
        ],
        [
          'ผู้อนุมัติ/ปิดงาน (QA)',
          job.approvedBy || '-',
          job.closedDateTime || '-',
          isFinal ? 'CLOSED' : 'PENDING'
        ]
      ]
    )
  );

  parts.push(
    '<table class="footer-table">',
      '<tr>',
        '<td>Revise: 00 / Issue Date: September 01, 2026</td>',
        '<td class="footer-right">Doc No.: LTE-FM-DC-38</td>',
      '</tr>',
    '</table>',

    '</body>',
    '</html>'
  );

  return parts.join('');
}


