/* =====================================================
   PDF SECTION HTML
===================================================== */
function pdfSectionTableHtml_(title, rows) {

  const out = [];

  out.push(
    '<div class="section">',
      '<div class="section-title">',
        pdfEscapeHtml_(title),
      '</div>',
      '<table class="form-table">'
  );

  (rows || []).forEach(function(row) {

    if (row.type === 'two') {

      out.push(
        '<tr>',
          '<td class="label">',
            pdfEscapeHtml_(
              pdfSafeText_(row.values[0])
            ),
          '</td>',
          '<td colspan="3">',
            pdfEscapeHtml_(
              pdfSafeText_(row.values[1])
            ),
          '</td>',
        '</tr>'
      );

    } else {

      out.push(
        '<tr>',
          '<td class="label">',
            pdfEscapeHtml_(
              pdfSafeText_(row.values[0])
            ),
          '</td>',
          '<td class="value">',
            pdfEscapeHtml_(
              pdfSafeText_(row.values[1])
            ),
          '</td>',
          '<td class="label">',
            pdfEscapeHtml_(
              pdfSafeText_(row.values[2])
            ),
          '</td>',
          '<td class="value">',
            pdfEscapeHtml_(
              pdfSafeText_(row.values[3])
            ),
          '</td>',
        '</tr>'
      );

    }

  });

  out.push(
      '</table>',
    '</div>'
  );

  return out.join('');
}


/* =====================================================
   PDF IMAGE SECTION
===================================================== */
function pdfImageSectionHtml_(title, images) {

  const list =
    images || [];

  const out = [];

  out.push(
    '<div class="section">',
      '<div class="section-title">',
        pdfEscapeHtml_(title),
      '</div>',
      '<table class="image-table">'
  );

  if (list.length === 0) {

    out.push(
      '<tr>',
        '<td colspan="3" class="empty-image">',
          'ไม่มีรูปภาพ',
        '</td>',
      '</tr>'
    );

  } else {

    for (
      let i = 0;
      i < list.length;
      i += 3
    ) {

      out.push('<tr>');

      for (
        let c = 0;
        c < 3;
        c++
      ) {

        const index =
          i + c;

        if (
          index >= list.length
        ) {

          out.push(
            '<td></td>'
          );

          continue;
        }

        const image =
          list[index];

        const dataUri =
          pdfImageDataUri_(image);

        const caption =
          'ภาพที่ ' +
          (index + 1) +
          ' : ' +
          pdfSafeText_(
            image.description ||
            image.fileName
          );

        out.push('<td>');

        if (dataUri) {

          out.push(
            '<img class="pdf-image" src="',
              dataUri,
            '">'
          );

        } else {

          out.push(
            '<div>',
              'ไม่สามารถแสดงรูป: ',
              pdfEscapeHtml_(
                image.fileName || '-'
              ),
            '</div>'
          );

        }

        out.push(
          '<div class="image-caption">',
            pdfEscapeHtml_(caption),
          '</div>',
        '</td>'
        );

      }

      out.push('</tr>');

    }

  }

  out.push(
      '</table>',
    '</div>'
  );

  return out.join('');
}


/* =====================================================
   PDF SIGNOFF HTML
===================================================== */
function pdfSignoffHtml_(title, rows) {

  const out = [];

  out.push(
    '<div class="section">',
      '<div class="section-title">',
        pdfEscapeHtml_(title),
      '</div>',
      '<table class="form-table">',
        '<tr>',
          '<td class="label">ลงนาม (SIGN-OFF)</td>',
          '<td class="label">ผู้ลงนาม (Name)</td>',
          '<td class="label">วันที่ (Date)</td>',
          '<td class="label">สถานะงาน (Status)</td>',
        '</tr>'
  );

  (rows || []).forEach(function(row) {

    out.push(
      '<tr>',
        '<td>',
          pdfEscapeHtml_(
            pdfSafeText_(row[0])
          ),
        '</td>',
        '<td>',
          pdfEscapeHtml_(
            pdfSafeText_(row[1])
          ),
        '</td>',
        '<td>',
          pdfEscapeHtml_(
            pdfSafeText_(row[2])
          ),
        '</td>',
        '<td>',
          pdfEscapeHtml_(
            pdfSafeText_(row[3])
          ),
        '</td>',
      '</tr>'
    );

  });

  out.push(
      '</table>',
    '</div>'
  );

  return out.join('');
}


/* =====================================================
   PDF DRIVE IMAGE -> DATA URI
===================================================== */
function pdfImageDataUri_(image) {
  if (/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(image.dataUri||'')) return image.dataUri;
  try {const u=new URL(image.url);if(u.protocol==='https:'&&u.hostname===new URL(QA_CONFIG.supabaseUrl).hostname)return pdfEscapeHtml_(u.href);}catch(e){}
  return '';
}

/* =====================================================
   PDF UTIL
===================================================== */
function pdfSafeText_(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return '-';
  }

  const text =
    String(value);

  if (
    text.trim() === ''
  ) {
    return '-';
  }

  return text;

}


function pdfEscapeHtml_(value) {

  return String(
    value === null ||
    value === undefined
      ? ''
      : value
  )
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

}




/* Browser report generation replaces Utilities.newBlob(...).getAs(PDF).
   The original report fields, logo, DRAFT/FINAL convention and round ordering are retained.
   html2pdf renders a raster PDF; Print / Save PDF uses the browser's native print engine.
   PDFs are versioned snapshots in private Storage, not cryptographically signed records. */
(() => {
  QA.pdfVersion='33.1.1';
  const PDF_LIBRARY='https://cdn.jsdelivr.net/npm/html2pdf.js@0.14.0/dist/html2pdf.bundle.min.js';
  const readDataUri=blob=>new Promise((resolve,reject)=>{
    const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Cannot read report image'));r.readAsDataURL(blob);
  });
  async function reportData(jobId,embed) {
    const {job}=await QA.api.getJob(jobId,{track:false});
    if(embed) {
      const images=[...job.beforeImages,...job.correctiveLogs.flatMap(l=>l.afterImages||[])];
      let bytes=0;
      for(const image of images) {
        const {data,error}=await QA.client.storage.from(QA_CONFIG.imageBucket).download(image.storagePath);
        if(error)throw error;
        bytes+=data.size;
        if(bytes>40*1024*1024)throw new Error('Report images exceed the 40 MiB export limit. This report needs a server-side PDF renderer; no new PDF has been saved.');
        image.dataUri=await readDataUri(data);
      }
    }
    const isFinal=job.status==='CLOSED',documentType=isFinal?'FINAL':'DRAFT';
    return {job,documentType,html:buildJobPdfHtml_(job,documentType,isFinal)};
  }
  async function imagesReady(doc) {
    await doc.fonts?.ready;
    await Promise.all([...doc.images].map(img=>img.decode().catch(()=>{throw new Error('A report image could not load. Refresh the job and try again.');})));
  }
  function frameFor(html,library) {
    const frame=document.createElement('iframe');
    frame.style.cssText='position:fixed;left:-12000px;top:0;width:800px;height:1100px;border:0;';
    frame.setAttribute('aria-hidden','true');
    const loaded=new Promise((resolve,reject)=>{
      const timer=setTimeout(()=>reject(new Error('PDF library timed out. Check the network/CDN connection and try again.')),30000);
      frame.onload=()=>{clearTimeout(timer);resolve(frame);};
    });
    if(library) html=html.replace('</head>','<script src="'+PDF_LIBRARY+'"></script></head>');
    frame.srcdoc=html;document.body.append(frame);
    return {frame,loaded};
  }
  let exporting=false;
  QA.exportReport=async jobId=>{
    if(exporting)throw new Error('A report is already being generated.');exporting=true;
    let holder;
    try {
      const {job,documentType,html}=await reportData(jobId,true);
      holder=frameFor(html,true);await holder.loaded;
      const w=holder.frame.contentWindow,d=holder.frame.contentDocument;
      if(!w.html2pdf)throw new Error('html2pdf could not load. Check the Internet/CDN connection and try again.');
      await imagesReady(d);
      const scale=Math.min(1.5,12000/Math.max(1,d.body.scrollHeight));
      if(scale<0.7)throw new Error('Report is too long for the browser PDF renderer. This report needs a server-side PDF renderer; no new PDF has been saved.');
      const fileName=job.jobId+'_'+documentType+'_v'+job.version+'.pdf';
      // html2pdf 0.14.0 checks obj.constructor === Array. Arrays created in the
      // parent page fail this check in the iframe, even with four valid values.
      // Create ALL options in the library's realm, without eval or changing the
      // original top/left/bottom/right margins (12/13/12/13 mm).
      // These options must remain JSON-only; put no callbacks in this object.
      const options=w.JSON.parse(JSON.stringify({filename:fileName,margin:[12,13,12,13],
        image:{type:'jpeg',quality:0.94},html2canvas:{scale,useCORS:true,logging:false},
        jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},
        pagebreak:{mode:['css','legacy'],avoid:['.header','.form-table tr','.image-table tr','.footer-table']}
      }));
      const frameBlob=await w.html2pdf().set(options).from(d.body).outputPdf('blob');
      if(!frameBlob || typeof frameBlob.arrayBuffer!=='function' || !frameBlob.size)
        throw new Error('PDF renderer returned an empty or invalid file. No new PDF has been saved.');
      if(frameBlob.size>20*1024*1024)
        throw new Error('Generated PDF exceeds the 20 MiB report limit. No new PDF has been saved.');
      // Normalize the cross-frame Blob for the parent-page Storage SDK.
      const blob=new Blob([frameBlob],{type:'application/pdf'});
      if(await blob.slice(0,5).text()!=='%PDF-')
        throw new Error('PDF renderer returned a non-PDF file. No new PDF has been saved.');
      // Prepare preview bytes before saving so a FileReader failure does not
      // look like an unsuccessful export after a successful database commit.
      const dataUri=await readDataUri(blob);
      const base64=String(dataUri).split(',')[1];
      if(!base64)throw new Error('Could not prepare the PDF preview. No new PDF has been saved.');
      const saved=await QA.saveReport(jobId,job.version,blob,fileName);
      if(!saved?.success)throw new Error('PDF save was not confirmed. Check the report records before retrying.');
      return {...saved,fileName,mimeType:'application/pdf',documentType,base64};
    } finally {holder?.frame.remove();exporting=false;}
  };
  // Kept for compatibility; the V33.1.1 job page has no extra local-print button.
  QA.printReport=async jobId=>{
    const popup=window.open('','_blank');
    if(!popup){QA.notify('Allow pop-ups for this site.');return;}
    popup.document.write('<!doctype html><meta charset="utf-8"><p>Loading report...</p>');popup.document.close();
    try {
      const {html}=await reportData(jobId,false);
      const toolbar='<div class="print-toolbar"><button onclick="window.print()">Print / Save as PDF</button><p>This local print is not automatically saved to Supabase.</p></div>';
      const printable=html.replace('</head>','<style>.print-toolbar{padding:12px;background:#eef2f7;margin:12px 0}@media print{.print-toolbar{display:none}}.section{break-inside:auto}.form-table td{white-space:pre-wrap}</style></head>').replace('<body>','<body>'+toolbar);
      popup.document.open();popup.document.write(printable);popup.document.close();
      await imagesReady(popup.document);
      popup.focus();
    }catch(e){popup.document.body.textContent=QA.errorOf(e).message;QA.notify(QA.errorOf(e).message);}
  };
})();
